'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var common = require( './common.js' );
var publicMain = require( './../lib' );
var native = tryRequire(resolve(__dirname, '../lib/native.js'));
var addon = tryRequire(resolve(__dirname, '../src/addon.node'));
var opts = {
	'skip': ((native instanceof Error) || (addon instanceof Error))
};


// TESTS //

tape('main export is a function', opts, function test(t) {
	t.ok( true, __filename );
	t.strictEqual(typeof addon, 'function', 'actual addon loaded');
	t.strictEqual(publicMain, native, 'public uses compiled native interface');
	common.check(t, native);
	t.end();
});
tape('raw bridge validates active geometry before staging and writes', opts, function test(t) {
	var before;
	var a = new Float64Array([
		4,
		0,
		0,
		9
	]);
	var p = new Int32Array([
		-3,
		-4
	]);
	var r = new Int32Array([7]);
	var w = new Float64Array([
		11,
		12,
		13,
		14
	]);
	before = [
		common.snapshot(a, false),
		common.snapshot(p, true),
		common.snapshot(r, true),
		common.snapshot(w, false)
	];
	t.throws(function call() {
		addon(121, 2, a, 0, 0, 0, p, 1, 0, r, 0, -1, w, 1, 0);
	}, RangeError, 'raw matrix broadcast');
	t.throws(function call() {
		addon(121, 2, a, 1, 1, 0, p, 1, 0, r, 0, -1, w, 1, 0);
	}, RangeError, 'raw matrix collision');
	t.throws(function call() {
		addon(121, 2, a, 2, 1, 0, p, 1, 0, r, 0, -1, a, 1, 0);
	}, RangeError, 'raw physical overlap');
	t.throws(function call() {
		addon(121, 2, a, 2, 1, 0, p, 1, 0, r, 0, NaN, w, 1, 0);
	}, RangeError, 'raw finite TOL before active buffers');
	t.throws(function call() {
		addon(121, 2, a, 2, 1, 0, p, 1, 0, r, 0, '-1', w, 1, 0);
	}, TypeError, 'raw primitive TOL');
	t.throws(function call() {
		addon(121, 2, a, 2, 1, 0, p, 1, 0, r, 0, -1, w, 0, 0);
	}, RangeError, 'raw scratch broadcast');
	t.throws(function call() {
		addon(121, 1, a, 2147483648, 0, 0, p, 0, 0, r, 0, -1, w, 1, 0);
	}, RangeError, 'raw conservative metadata cap');
	t.deepEqual([
		common.snapshot(a, false),
		common.snapshot(p, true),
		common.snapshot(r, true),
		common.snapshot(w, false)
	], before, 'all rejected calls precede writes');
	t.strictEqual(addon(121, 0, null, null, null, null, null, null, null, r, 0, -1, null, null, null), 0, 'raw empty rank only');
	t.strictEqual(r[0], 0, 'raw rank zero');
	t.end();
});
